create or replace function audit_notification_runtime_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  metadata_key text;
begin
  metadata_key := case
    when tg_op = 'DELETE' then coalesce(
      to_jsonb(old)->>'key',
      to_jsonb(old)->>'template_key',
      to_jsonb(old)->>'id'
    )
    else coalesce(
      to_jsonb(new)->>'key',
      to_jsonb(new)->>'template_key',
      to_jsonb(new)->>'id'
    )
  end;

  if auth.uid() is not null then
    perform create_audit_log(
      'notification_runtime.' || lower(tg_op),
      tg_table_name,
      null,
      jsonb_build_object('key', metadata_key)
    );
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

